mapper.select:
SELECT mld.*, (mld.required_quantity - mld.picked_quantity + mld.returned_quantity) as remaining_quantity, CASE mld.pick_status WHEN 'PENDING' THEN '待领料' WHEN 'PICKING' THEN '领料中' WHEN 'PICKED' THEN '已领料' WHEN 'COMPLETED' THEN '完成' ELSE mld.pick_status END as pick_status_name FROM mes_material_list_detail mld WHERE mld.del_flag = '0' AND mld.material_code = #{materialCode}
AND mld.factory_code = #{factoryCode}
ORDER BY mld.create_time DESC
